const config = {
  publishingEnabled: false,
  allowedMediaHosts: [], // Add exact HTTPS CDN hostnames returned by your render account.
  maxMediaBytes: 100 * 1024 * 1024
};
if (!config.publishingEnabled) return [];
if (!Array.isArray(config.allowedMediaHosts) || !config.allowedMediaHosts.length ||
    config.allowedMediaHosts.some(h => typeof h !== 'string' || !/^[a-z0-9.-]+$/.test(h) || h.includes('*'))) {
  throw new Error('Set exact allowedMediaHosts before enabling publication');
}
if (!Number.isSafeInteger(config.maxMediaBytes) || config.maxMediaBytes < 1) throw new Error('Invalid media size limit');
return [{json:config}];

const row=$input.first().json, owner=$('Publisher Config').first().json;
const a=row.asset, c=row.config;
if (!a || !c || a.id!==row.asset_id || !/^[a-f0-9]{64}$/i.test(a.sha256||'')) throw new Error('Missing immutable approved asset');
if (!['youtube_long','youtube_short','instagram_reel','instagram_image'].includes(a.format)) throw new Error('Unsupported approved format');
const isYouTube=a.format.startsWith('youtube_');
if (typeof a.target_id!=='string' || !a.target_id || a.target_id!==(isYouTube?c.youtubeChannelId:c.instagramUserId)) throw new Error('Frozen target does not match configured account');
if (typeof a.made_for_kids!=='boolean' || typeof a.contains_synthetic_media!=='boolean') throw new Error('Explicit audience and synthetic disclosure required');
if (typeof a.title!=='string' || !a.title.trim() || (isYouTube && a.title.length>100) || typeof a.caption!=='string') throw new Error('Invalid approved metadata');
if ((isYouTube && !['public','private','unlisted'].includes(a.visibility)) || (!isYouTube && a.visibility!=='public')) throw new Error('Invalid approved visibility');
if (isYouTube ? Buffer.byteLength(a.caption,'utf8')>5000 : a.caption.length>2200) throw new Error('Caption exceeds provider limit');
if (!isYouTube && (!/^\d+$/.test(c.instagramUserId)||!/^v\d+\.\d+$/.test(c.instagramApiVersion))) throw new Error('Pinned Instagram version and numeric account ID required');
const size=Number(a.bytes);
if (!Number.isSafeInteger(size)||size<=0||size>owner.maxMediaBytes) throw new Error('Approved media exceeds configured download limit');
const match=/^https:\/\/([a-zA-Z0-9.-]+)(\/[^#]*)$/.exec(a.media_url||'');
if (!match || !owner.allowedMediaHosts.includes(match[1].toLowerCase())) throw new Error('Media URL is outside approved HTTPS render hosts');
return [{json:{...row,asset:{...a,bytes:size},platform:isYouTube?'youtube':'instagram'}}];

const input=$input.first(), row=$('Validate Approved Asset').first().json;
const data=await this.helpers.getBinaryDataBuffer(0,'data');
if (input.json.actual_sha256!==row.asset.sha256 || data.length!==row.asset.bytes) throw new Error('Media changed after approval; regenerate and approve a new revision');
return [{json:row,binary:input.binary}];

const row=$('Verify Exact Media').first().json, items=$input.first().json.items;
if (!Array.isArray(items)||items.length!==1||items[0].id!==row.asset.target_id||items[0].id!==row.config.youtubeChannelId) throw new Error('OAuth channel does not uniquely match the approved YouTube target');
return [{json:row}];

const response=$input.first().json, row=$('Verify Exact Media').first().json;
const location=response.headers?.location||response.headers?.Location;
if (typeof location!=='string'||!/^https:\/\/www\.googleapis\.com\/upload\/youtube\/v3\/videos\?[^#\s]+$/.test(location)) throw new Error('Missing or untrusted resumable upload location');
return [{json:{...row,checkpoint:{stage:'uploading',upload_url:location,total_bytes:row.asset.bytes}}}];

const id=$input.first().json.id;
if (typeof id!=='string'||!/^[A-Za-z0-9_-]+$/.test(id)) throw new Error('Upload response lacks a video ID; inspect saved resumable session');
return [{json:{result:{platform:'youtube',external_id:id,url:'https://www.youtube.com/watch?v='+id}}}];

const row=$('Verify Exact Media').first().json, body=$input.first().json;
const rows=body.data??[body];
if (!Array.isArray(rows)||rows.length!==1||String(rows[0].user_id)!==row.asset.target_id||String(rows[0].user_id)!==row.config.instagramUserId||!['BUSINESS','MEDIA_CREATOR'].includes(String(rows[0].account_type).toUpperCase())) throw new Error('Instagram token does not identify the approved professional account');
return [{json:row}];

const id=$input.first().json.id, row=$('Verify Exact Media').first().json;
if (typeof id!=='string'||!/^\d+$/.test(id)) throw new Error('Instagram container creation returned no valid ID');
return [{json:{...row,container_id:id,checkpoint:{stage:'container',container_id:id}}}];

const status=$input.first().json.status_code, attempt=$runIndex+1;
let poll_state='uncertain';
if (status==='FINISHED') poll_state='ready';
else if (status==='IN_PROGRESS') poll_state=attempt<5?'wait':'failed';
else if (['ERROR','EXPIRED'].includes(status)) poll_state='failed';
return [{json:{...$('Validate Instagram Container').first().json,poll_state,poll_attempt:attempt,container_status:status}}];

const id=$input.first().json.id;
if (typeof id!=='string'||!/^\d+$/.test(id)) throw new Error('Instagram publication ID unknown; never resubmit media_publish');
return [{json:{checkpoint:{stage:'published_id',publish_attempted:true,container_id:$('Validate Instagram Container').first().json.container_id,media_id:id}}}];

const response=$input.first().json, id=$('Validate Instagram Media ID').first().json.checkpoint.media_id;
if (response.id!==id||typeof response.permalink!=='string'||!/^https:\/\/(?:www\.)?instagram\.com\/(?:p|reel|tv)\/[A-Za-z0-9_-]+\/?(?:\?[^#]*)?$/.test(response.permalink)) throw new Error('Media ID saved but permalink unavailable; reconcile without republishing');
return [{json:{result:{platform:'instagram',external_id:id,url:response.permalink}}}];

