WITH marked AS (
 UPDATE yt_agent.publications SET status='failed',error=$2,updated_at=now()
 WHERE id=$1::uuid AND status='publishing' RETURNING job_id,id,checkpoint
), logged AS (
 INSERT INTO yt_agent.audit(job_id,event,detail) SELECT job_id,'publication_failed',jsonb_build_object('publication_id',id,'checkpoint',checkpoint) FROM marked
)
UPDATE yt_agent.jobs j SET status='partial',error=$2,updated_at=now() FROM marked m WHERE j.id=m.job_id RETURNING j.id::text AS job_id,j.status,m.checkpoint;

WITH marked AS (
 UPDATE yt_agent.publications SET status='uncertain',error=$2,updated_at=now()
 WHERE id=$1::uuid AND status='publishing' RETURNING job_id,id,checkpoint
), logged AS (
 INSERT INTO yt_agent.audit(job_id,event,detail) SELECT job_id,'publication_uncertain',jsonb_build_object('publication_id',id,'checkpoint',checkpoint) FROM marked
)
UPDATE yt_agent.jobs j SET status='uncertain',error=$2,updated_at=now() FROM marked m WHERE j.id=m.job_id RETURNING j.id::text AS job_id,j.status,m.checkpoint;
